import { findType } from '../registry.js'
import { listChanges, listResources, readChange } from '../store.js'
import type { ResourceTypeSpec } from '../types.js'
import { auditChange } from './audit.js'
import {
  type ChangePlan,
  type HubActor,
  type PlanRequestOp,
  ResourceChangeError,
  type StoredChangePlan
} from './contract.js'
import { desiredFromObservedFields } from './plan.js'
import { createPlannedChange } from './run.js'

/**
 * Decision 5: undo is generated by the engine — a NEW planned change from what the resources are
 * now back to the before-state the original change recorded, through every gate again:
 *
 *  - a create is undone by deleting what it made;
 *  - an update / replace by an update back to the stored desired fields before it (fields the
 *    change added are cleared); every changed field must be reversible for the type;
 *  - a delete by creating it again from its before-state (a type with a snapshot keeps the
 *    snapshot ref on the original step; restoring from it is the adapter's own create);
 *  - adopt / accept change nothing at the provider and are not undone.
 * Only the newest change of its resources can be undone (NOT_REVERSIBLE otherwise).
 */

const refuse = (message: string) => new ResourceChangeError('NOT_REVERSIBLE', message)

function reversibleFields(type: ResourceTypeSpec, fields: string[]): boolean {
  if (typeof type.reversible === 'boolean') return type.reversible
  const fn = type.reversible
  return fields.every((f) => fn(f))
}

export async function undoChange(changeId: number, actor: HubActor): Promise<ChangePlan> {
  const row = await readChange(Number(changeId))
  if (!row) throw new ResourceChangeError('NOT_FOUND', 'No such change.')
  if (row.status !== 'applied' || !row.plan)
    throw new ResourceChangeError('BAD_STATUS', 'Only an applied change can be undone.')
  const plan = row.plan as StoredChangePlan
  const touched = new Set<number>()
  for (const s of row.steps)
    if (s.status === 'done' && s.resourceId != null) touched.add(s.resourceId)
  if (!touched.size)
    throw refuse('This change did nothing at the provider; there is nothing to undo.')

  // Only the newest change of these resources.
  const later = await listChanges({
    connectionId: row.connection_id,
    status: ['applied', 'applying', 'interrupted', 'failed', 'pending_approval'],
    limit: 200
  })
  for (const c of later) {
    if (c.id <= row.id) continue
    const ids = new Set<number>([
      ...(c.plan?.resourceIds ?? []).filter((x): x is number => x != null),
      ...c.steps.map((s) => s.resourceId).filter((x): x is number => x != null)
    ])
    if ([...touched].some((id) => ids.has(id)) && c.status !== 'planned')
      throw refuse(
        `Change ${c.id} changed these resources later; only the newest change can be undone.`
      )
  }

  const live = new Map(
    (await listResources({ ids: [...touched], includeDeleted: true })).map((r) => [r.id, r])
  )
  const peers = await listResources({ connectionId: row.connection_id })
  const byExternal = new Map(peers.map((p) => [`${p.type}\0${p.external_id}`, p.id]))
  const rowOf = (t: string, ext: string) => byExternal.get(`${t}\0${ext}`) ?? null

  // Per source request op: what it did, newest first (deletes of children before parents).
  const bySource = new Map<number, number[]>()
  plan.ops.forEach((_, i) => {
    if (row.steps[i]?.status !== 'done') return
    const src = plan.sources?.[i] ?? i
    bySource.set(src, [...(bySource.get(src) ?? []), i])
  })
  const ops: PlanRequestOp[] = []
  const sources = [...bySource.keys()].sort((a, b) => {
    // Reverse of the order they ran in.
    const fa = Math.min(...(bySource.get(a) ?? [0]))
    const fb = Math.min(...(bySource.get(b) ?? [0]))
    return fb - fa
  })
  for (const src of sources) {
    const idx = bySource.get(src) ?? []
    const first = row.steps[idx[0]]
    const kinds = idx.map((i) => plan.ops[i])
    if (kinds.every((o) => o.kind === 'noop')) continue
    const type = findType(kinds[0].type)?.type
    if (!type) throw refuse(`The type ${kinds[0].type} is no longer registered.`)
    const resourceId = first.resourceId
    const res = resourceId != null ? live.get(resourceId) : undefined
    const changed = [...new Set(kinds.flatMap((o) => o.changes.map((c) => c.field)))]
    if (!reversibleFields(type, changed))
      throw refuse(`${type.label}: this change cannot be undone by the Hub.`)
    if (kinds.some((o) => o.kind === 'create')) {
      if (!res || res.deleted_at) continue
      ops.push({ action: 'delete', resourceId: res.id })
    } else if (kinds.some((o) => o.kind === 'delete')) {
      if (first.result?.answer?.already_gone === true) continue
      const before =
        first.beforeDesired ?? desiredFromObservedFields(type, first.before, rowOf).fields
      if (!before || !Object.keys(before).length)
        throw refuse(`${type.label}: the Hub kept no before-state to recreate it from.`)
      ops.push({ action: 'create', type: type.key, fields: before })
    } else {
      if (!res || res.deleted_at)
        throw refuse(`${type.label} is gone; there is nothing to put back.`)
      const before =
        first.beforeDesired ??
        (first.before ? desiredFromObservedFields(type, first.before, rowOf).fields : null)
      if (!before) throw refuse(`${type.label}: the Hub kept no before-state to go back to.`)
      const fields: Record<string, unknown> = { ...before }
      for (const k of Object.keys(res.desired ?? {})) if (!(k in fields)) fields[k] = null
      ops.push({ action: 'update', resourceId: res.id, fields })
    }
  }
  if (!ops.length) throw refuse('Nothing of this change is left to undo.')
  const out = await createPlannedChange(
    {
      connectionId: row.connection_id,
      scope: row.scope,
      ...(row.app_id != null ? { appId: row.app_id } : {}),
      ...(row.environment_id != null ? { environmentId: row.environment_id } : {}),
      ops
    },
    actor,
    { mode: 'internal', undoOf: row.id }
  )
  await auditChange('hub-resource-change-undo-plan', actor.id, row, {
    undo_change_id: out.changeId
  })
  return out
}
